from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrbtsParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mcc, mnc = self.enb_ent_config['mcc'], self.enb_ent_config['mnc']

        self.set_parameter('gNbCuName', 'CU_' + self.enb_ent_config['id'].zfill(3))
        self.set_parameter('gNbCuType', self.enb_ent_config['type'])
        self.set_parameter('mnc', mnc)
        self.set_parameter('mcc', mcc)
        self.set_parameter('mncLength', self.get_len_str(mnc))

        self.set_optional()

    def set_optional(self):
        tnl_conf = self.enb_ent_config.get('tnl_conf')
        bts_id = self.enb_ent_config['id']
        SA = {
            'actAdditionalSliceSupport': 'true',
            'applyPriorityAccess': 'HPA+MPS',
            'drbInactivityTimerSA': '60',
            'drxDefaultPaging': 'v256',
            'ngUeRetentionTmr': '10',
            'tDCoverall': '2000',
            'timerX2UeProcGuard': '2000',
            'x2EnDcCfUpNbInfoBackOffTmr': '300',
        }
        SA_NSA = {
            'actMultiDrbNSA': 'true',
            'drbInactivityTimerSA': '600',
            'ngInducedCellDeactDelayTimer': '10',
            's1Uplane': ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-3/IPNO-1/IPIF-4/IPADDRESSV4-1'],
            'srbInactivityTimerSA': '600',
            'tRLFindForDUSA': '2000ms',
            'timerXnDataFwdGuard': '2000',
            'waitForRecovBeforeCellBarringTimer': '10',
            'x2Cplane': ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-4/IPADDRESSV4-1'],
            'x2Uplane': ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-3/IPNO-1/IPIF-4/IPADDRESSV4-1'],
        }

        if tnl_conf:
            self.set_tnl_conf_sa_nsa(tnl_conf, SA_NSA, bts_id)

        params = {}
        if self.is_sa:
            params = SA
        elif self.is_sa_nsa:
            params = SA_NSA

        for par, val in params.items():
            if isinstance(val, list):
                self.set_struct_parameter(par, val[0], val[1])
            else:
                self.set_parameter(par, val)

        self.set_parameter('actBtcOvlProt', 'false')
        self.set_parameter('actCellTraceReport', 'true')
        self.set_parameter('actIncXn', 'true')
        self.set_parameter('actNgcFlexSaMode', 'true')
        self.set_parameter('actRobustnessXnAndX2', 'false')
        self.set_struct_parameter('cuFlowControlProf', 'minThFlowCtrl', '10')
        self.set_parameter('e1NbResetRetryForFault', '3')
        self.set_parameter('e1SetupTimeToWait', '10s')
        self.set_parameter('f1MaxParallelIncSetup', '128')
        self.set_parameter('enDcX2SetupReqTmr', '300')
        self.set_parameter('maxNumX2Links', '128')
        self.set_parameter('maxParallelXnSetup', '128')
        self.set_parameter('nsaInactivityTimer', '1000')
        self.set_parameter('rejectSuppBcs', 'none')
        self.set_parameter('tNgRelocOverall', '3000')
        self.set_parameter('tNgRelocPrep', '2000')
        self.set_parameter('timerE1BearerProcGuard', '25')
        self.set_parameter('timerE1ResetGuard', '25')
        self.set_parameter('timerX2DataFwdGuard', '250')
        self.set_parameter('x2LinkSupervisionTmr', '0')
        self.set_parameter('xnNgRanCfUpNbInfoBackOffTmr', '300')
        if tnl_conf:
            self.set_tnl_conf(tnl_conf, bts_id)
        else:
            self.set_struct_parameter('f1Cplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-2/IPADDRESSV4-1')
            self.set_struct_parameter('f1Uplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-3/IPNO-1/IPIF-2/IPADDRESSV4-1')
            self.set_struct_parameter('ngCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-1/IPADDRESSV4-1')
            self.set_struct_parameter('ngUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-3/IPNO-1/IPIF-1/IPADDRESSV4-1')
            self.set_struct_parameter('xnCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-2/IPNO-1/IPIF-3/IPADDRESSV4-1')
            self.set_struct_parameter('xnUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/TNL-3/IPNO-1/IPIF-3/IPADDRESSV4-1')
        self.set_parameter('sgnbRelForNoHandoverEnabled', 'true')

    def set_tnl_conf_sa_nsa(self, tnl_conf, SA_NSA, bts_id):
        if tnl_conf.get('x2c'):
            SA_NSA['x2Cplane'] = ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("x2c")}/IPADDRESSV4-1']
        if tnl_conf.get('x2u'):
            SA_NSA['x2Uplane'] = ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("x2u")}/IPADDRESSV4-1']
        if tnl_conf.get('s1u'):
            SA_NSA['s1Uplane'] = ['ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("s1u")}/IPADDRESSV4-1']

    def set_tnl_conf(self, tnl_conf, bts_id):
        if tnl_conf.get('f1c'):
            self.set_struct_parameter('f1Cplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("f1c")}/IPADDRESSV4-1')
        if tnl_conf.get('f1u'):
            self.set_struct_parameter('f1Uplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("f1u")}/IPADDRESSV4-1')
        if tnl_conf.get('ngc'):
            self.set_struct_parameter('ngCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("ngc")}/IPADDRESSV4-1')
        if tnl_conf.get('ngu'):
            self.set_struct_parameter('ngUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("ngu")}/IPADDRESSV4-1')
        if tnl_conf.get('xnc'):
            self.set_struct_parameter('xnCplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("xnc")}/IPADDRESSV4-1')
        if tnl_conf.get('xnu'):
            self.set_struct_parameter('xnUplane', 'ipV4AddressDN1', f'MRBTS-{bts_id}/TNLSVC-1/{tnl_conf.get("xnu")}/IPADDRESSV4-1')
